// with ensure_ascii: \" \\ \n \r \t \b \f, other controls and every
// non-ASCII code point as \uXXXX (astral ones as a surrogate pair). Outside
// python mode it escapes only what JSON requires, plus < > & as Go does not
// need to: the body is read by programs.
func (w *jsonWriter) str(s string) {
	w.b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			w.b.WriteString(`\"`)
		case '\\':
			w.b.WriteString(`\\`)
		case '\n':
			w.b.WriteString(`\n`)
		case '\r':
			w.b.WriteString(`\r`)
		case '\t':
			w.b.WriteString(`\t`)
		case '\b':
			w.b.WriteString(`\b`)
		case '\f':
			w.b.WriteString(`\f`)
		default:
			switch {
			case r < 0x20:
				fmt.Fprintf(&w.b, `\u%04x`, r)
			case r < 0x80 || !w.python:
				w.b.WriteRune(r)
			case r > 0xffff:
				r -= 0x10000
				fmt.Fprintf(&w.b, `\u%04x\u%04x`, 0xd800+(r>>10), 0xdc00+(r&0x3ff))
			default:
				fmt.Fprintf(&w.b, `\u%04x`, r)
			}
		}
	}
	w.b.WriteByte('"')
}

