    }
    for (uint g = 0u; g < NKV; g++) {
        float y = normRope(act[p + 8192u + g * HD + t], pc.wOff + HD, pos);
        act[pc.kOff + (cell * NKV + g) * HD + t] = y;
        act[pc.vOff + (cell * NKV + g) * HD + t] = act[p + 9216u + g * HD + t];
