func (b *Buffer) WriteFloat32(src []float32) {
	dst := unsafe.Slice((*float32)(b.mapped), len(src))
	copy(dst, src)
}

// ReadFloat32 reads n float32s back out of the buffer's mapped memory.
func (b *Buffer) ReadFloat32(n int) []float32 {
	src := unsafe.Slice((*float32)(b.mapped), n)
	out := make([]float32, n)
	copy(out, src)
	return out
}

// WriteFloat32At copies src into the buffer's mapped memory at an element
// offset, so several tensors can share one arena.
func (b *Buffer) WriteFloat32At(off int, src []float32) {
	dst := unsafe.Slice((*float32)(b.mapped), off+len(src))
	copy(dst[off:], src)
}

// ReadFloat32At reads n float32s starting at an element offset. Reading a
// whole buffer to recover a tensor near its end is the difference between
// copying a few megabytes and copying gigabytes, which for the VAE decoder's
// activation arena was 23x the GPU time of the decode itself.
func (b *Buffer) ReadFloat32At(off, n int) []float32 {
	src := unsafe.Slice((*float32)(b.mapped), off+n)
	out := make([]float32, n)
	copy(out, src[off:])
	return out
}

// ReadFloat32Into is ReadFloat32At into a slice the caller keeps, for a
// tensor read over and over: a sequence checkpoint is 120 MB of recurrent
// state, and allocating it per read would be the same cost ZeroFloat32At
// exists to avoid (CONCURRENCY.md C4).
func newTestDevice(t *testing.T) (*vk.Device, func()) {
	t.Helper()
	inst, err := vk.NewInstance("qwen-test")
	if err != nil {
		t.Skipf("no Vulkan instance: %v", err)
	}
	devices, err := inst.PhysicalDevices()
	if err != nil || len(devices) == 0 {
		inst.Destroy()
		t.Skipf("no Vulkan devices: %v", err)
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
			break
		}
	}
	qf, err := phys.ComputeQueueFamily()
	if err != nil {
		inst.Destroy()
		t.Skipf("no compute queue: %v", err)
	}
	sgs, err := phys.SubgroupSizeControl()
	if err != nil {
		inst.Destroy()
		t.Skipf("no subgroup size control query: %v", err)
	}
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{
		Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported,
	})
	if err != nil {
		inst.Destroy()
		t.Skipf("no device: %v", err)
	}
	t.Logf("device: %s", phys.Name)
	return dev, func() { dev.Destroy(); inst.Destroy() }
}

