// Profile runs a pass one dispatch at a time and sums the GPU time by label
// over the layers. It is a measurement of the kernels, not of a pass: every
// dispatch pays its own submit.
func (g *GPU) Profile(enc *Encoding) (map[string]time.Duration, error) {
	segs, err := g.upload(enc)
	if err != nil {
		return nil, err
	}
	out := map[string]time.Duration{}
	for i := range g.w {
		d, labels := g.layerGraph(i, len(enc.IDs), segs)
		for j := range d {
			dur, err := vk.DispatchMultiTimed(d[j:j+1], 1, 1, true)
			if err != nil {
				return nil, fmt.Errorf("kev: layer %d %s: %w", i, labels[j], err)
			}
			out[labels[j]] += dur
		}
	}
	return out, nil
}
EOF
