#version 450

#extension GL_KHR_cooperative_matrix : enable
#extension GL_KHR_memory_scope_semantics : enable
#extension GL_KHR_shader_subgroup_basic : enable
#extension GL_EXT_shader_16bit_storage : enable
#extension GL_EXT_shader_explicit_arithmetic_types_float16 : enable
#extension GL_EXT_control_flow_attributes : enable

// Kev (CLASSIFICATION.md K7.1): llm_gemm.comp's plain int8 arm (MODE 2,
// -DQ8B), with the reduction split across the grid.
//
// The LLM's kernel was built for its prefill, where M is thousands of rows
// and a wave per 64-column tile is plenty of parallelism. A Kev request is
// tens to a few hundred rows, so the same kernel launches N/64 x M/BM
// single-wave workgroups: 40 for a 2560-wide output on a 40-CU device, a wave
// a CU, and a wave waiting on its int8 slab has nothing to hide behind. At 37
// tokens the whole model's weights read at ~125 GB/s of a bus that gives
// ~215.
//
// So K is split SPLITS ways across the grid's y (y = row block * SPLITS +
// slice): each workgroup reduces its own gemmK/SPLITS of the slab and writes
// a partial C into slice `slice` of the partial arena, and kev_splitk_reduce
// sums them. With SPLITS = 1 it is the LLM kernel's arithmetic exactly (one
// C, no reduce).
//
// The layout, the unpack and every other line are llm_gemm.comp's (see its
// header): int8 in the 16x16 fragment tiling, one fp16 scale per 32 k of a
// row in the plane after the tiles, the slab unpacked through LDS.
//
// Fields (llm_common.glsl's block): xnOff A (fp16 arena), lda; bOff B (bank,
// bytes); gemmM/N/K; outOff C, or the partial arena when split; hc the split
// count (SPLITS is also compiled in, and the host checks they agree).

#define DENSE_Q8 1
#include "llm_common.glsl"

#ifndef WM
#define WM 2
#endif
#ifndef WN
#define WN 4
#endif
#ifndef SPLITS
#define SPLITS 1
#endif
#define BK_TILES 2

#define TILE 16
#define BM (WM * TILE)
#define BN (WN * TILE)
#define BK (BK_TILES * TILE)
#define WAVE 64

layout(local_size_x = WAVE) in;

#define LDS_PAD 8
#define LDS_ROW (BK + LDS_PAD)
shared float16_t sQB[BN * LDS_ROW];

#define FRAG_A_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
#define FRAG_B_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
#define ACC_T coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>

void main() {
    uint wn0 = gl_WorkGroupID.x * BN;
    uint slice = gl_WorkGroupID.y % SPLITS;
    uint wm0 = (gl_WorkGroupID.y / SPLITS) * BM;

    ACC_T acc[WM][WN];
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            acc[i][j] = ACC_T(0.0);
        }
    }

    uint ktiles = pc.gemmK / TILE;
    uint qw0 = pc.bOff >> 2;
    uint sc0 = (pc.bOff + pc.gemmN * pc.gemmK) >> 1;
    uint kgroups = pc.gemmK >> 5;
    uint lane = gl_LocalInvocationID.x;
    uint nt0 = wn0 / TILE;

    uint kPer = pc.gemmK / SPLITS;
    uint kLo = slice * kPer, kHi = kLo + kPer;
    for (uint k0 = kLo; k0 < kHi; k0 += BK) {
        uint kt0 = k0 / TILE;
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            uint wbase = qw0 + ((nt0 + j) * ktiles + kt0) * 64u;
            uint sbase = sc0 + (nt0 + j) * kgroups * TILE;
            for (uint u = lane; u < BK_TILES * 64u; u += WAVE) {
                uint kt = u >> 6;
                uint b = (u & 63u) << 2;
                uint n = b >> 4;
                uint kk = b & 15u;
                uint word = w8[wbase + u];
                float d = float(w16[sbase + ((kt0 + kt) >> 1) * TILE + n]);
                uint dst = (j * TILE + n) * LDS_ROW + kt * TILE + kk;
                [[unroll]] for (uint t = 0u; t < 4u; t++) {
                    sQB[dst + t] = float16_t(float(bitfieldExtract(int(word), int(t * 8u), 8)) * d);
                }
            }
        }
        barrier();
        [[unroll]] for (uint kt = 0u; kt < BK_TILES; kt++) {
            FRAG_A_T fragA[WM];
            FRAG_B_T fragB[WN];
            [[unroll]] for (uint i = 0u; i < WM; i++) {
                coopMatLoad(fragA[i], hact, pc.xnOff + (wm0 + i * TILE) * pc.lda + k0 + kt * TILE,
                    pc.lda, gl_CooperativeMatrixLayoutRowMajor);
            }
            [[unroll]] for (uint j = 0u; j < WN; j++) {
                coopMatLoad(fragB[j], sQB, (j * TILE) * LDS_ROW + kt * TILE, LDS_ROW,
                    gl_CooperativeMatrixLayoutColumnMajor);
            }
            [[unroll]] for (uint i = 0u; i < WM; i++) {
                [[unroll]] for (uint j = 0u; j < WN; j++) {
                    acc[i][j] = coopMatMulAdd(fragA[i], fragB[j], acc[i][j]);
                }
            }
        }
        barrier();
    }

    uint out0 = pc.outOff + slice * pc.gemmM * pc.gemmN;
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            coopMatStore(acc[i][j], act, out0 + (wm0 + i * TILE) * pc.gemmN + wn0 + j * TILE, pc.gemmN,
                gl_CooperativeMatrixLayoutRowMajor);
        }
    }
}

