// Kev (CLASSIFICATION.md K7.1): sum kev_gemm_q8's split-K partials into C.
//
// C[r][c] = sum over s of P[s][r][c], one workgroup a row. The slices are
// summed in order, so a given split count always gives the same bits.
//
// Fields (dit_common.glsl): inOff the partials, aux1 the slice stride
// (gemmM * gemmN), aux0 the slice count; outOff C; dim N (both row strides);
// tokens the rows to write.

#version 450

#include "dit_common.glsl"

layout(local_size_x = 256) in;

void main() {
    uint r = gl_WorkGroupID.x;
    if (r >= pc.tokens) {
        return;
    }
    for (uint c = gl_LocalInvocationID.x; c < pc.dim; c += 256u) {
        uint i = r * pc.dim + c;
        float s = 0.0;
        for (uint k = 0u; k < pc.aux0; k++) {
            s += act[pc.inOff + k * pc.aux1 + i];
        }
        act[pc.outOff + i] = s;
    }
}
