python3 - <<'EOF'
p='shaders/kev_gemm_q8.comp'; s=open(p).read()
a=s.index('#ifndef WM'); 
head=s[:a]
head=head.replace('''// The layout, the unpack and every other line are llm_gemm.comp's (see its
// header)''','''// **What the profile then said, twice**: neither the unpack nor the
// parallelism is the limit. Every variant -- BM 16 to 128, one wave or eight,
// split or not -- cost about the same *per k-step*, because a k-step is a load
// of two words a lane, a barrier until they land, the unpack and the math,
// and nothing overlaps the next slab's DRAM latency with this slab's
// arithmetic. So this kernel pipelines: the next slab's words and scales are
// loaded into registers before the current slab is multiplied, and a slab is
// BK = 64 deep (BK_TILES = 4), sixteen words a lane in flight per step.
//
// The layout and the unpack arithmetic are llm_gemm.comp's (see its
// header)''')
body='''#ifndef WM
#define WM 2
#endif
#ifndef WN
#define WN 4
#endif
#ifndef SPLITS
#define SPLITS 1
#endif
#ifndef WAVES
#define WAVES 1
#endif
#ifndef BK_TILES
#define BK_TILES 4
#endif

#define TILE 16
#define BM (WAVES * WM * TILE)
#define BN (WN * TILE)
#define BK (BK_TILES * TILE)
#define WAVE 64
#define THREADS (WAVE * WAVES)
// Words of one n-tile's slab each thread fetches: a tile is 64 words.
#define PER (BK_TILES * 64 / THREADS)

layout(local_size_x = THREADS) in;

#define LDS_PAD 8
#define LDS_ROW (BK + LDS_PAD)
shared float16_t sQB[BN * LDS_ROW];

#define FRAG_A_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseA>
#define FRAG_B_T coopmat<float16_t, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseB>
#define ACC_T coopmat<float, gl_ScopeSubgroup, TILE, TILE, gl_MatrixUseAccumulator>

uint wq[WN][PER];
float wd[WN][PER];

// fetch loads the slab at k0 into registers: its words and each word's scale.
void fetch(uint k0, uint qw0, uint sc0, uint ktiles, uint kgroups, uint nt0, uint lane) {
    uint kt0 = k0 / TILE;
    [[unroll]] for (uint j = 0u; j < WN; j++) {
        uint wbase = qw0 + ((nt0 + j) * ktiles + kt0) * 64u;
        uint sbase = sc0 + (nt0 + j) * kgroups * TILE;
        [[unroll]] for (uint p = 0u; p < PER; p++) {
            uint u = lane + p * THREADS;
            uint kt = u >> 6;
            uint n = ((u & 63u) << 2) >> 4;
            wq[j][p] = w8[wbase + u];
            wd[j][p] = float(w16[sbase + ((kt0 + kt) >> 1) * TILE + n]);
        }
    }
}

// unpack writes the fetched slab into LDS as halves.
void unpack(uint lane) {
    [[unroll]] for (uint j = 0u; j < WN; j++) {
        [[unroll]] for (uint p = 0u; p < PER; p++) {
            uint u = lane + p * THREADS;
            uint kt = u >> 6;
            uint b = (u & 63u) << 2;
            uint dst = (j * TILE + (b >> 4)) * LDS_ROW + kt * TILE + (b & 15u);
            [[unroll]] for (uint t = 0u; t < 4u; t++) {
                sQB[dst + t] = float16_t(float(bitfieldExtract(int(wq[j][p]), int(t * 8u), 8)) * wd[j][p]);
            }
        }
    }
}

void main() {
    uint wn0 = gl_WorkGroupID.x * BN;
    uint slice = gl_WorkGroupID.y % SPLITS;
    uint wave = gl_LocalInvocationID.x / WAVE;
    uint wm0 = (gl_WorkGroupID.y / SPLITS) * BM + wave * WM * TILE; // this wave's rows

    ACC_T acc[WM][WN];
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            acc[i][j] = ACC_T(0.0);
        }
    }

    uint ktiles = pc.gemmK / TILE;
    uint qw0 = pc.bOff >> 2;
    uint sc0 = (pc.bOff + pc.gemmN * pc.gemmK) >> 1;
    uint kgroups = pc.gemmK >> 5;
    uint lane = gl_LocalInvocationID.x;
    uint nt0 = wn0 / TILE;

    uint kPer = pc.gemmK / SPLITS;
    uint kLo = slice * kPer, kHi = kLo + kPer;
    fetch(kLo, qw0, sc0, ktiles, kgroups, nt0, lane);
    for (uint k0 = kLo; k0 < kHi; k0 += BK) {
        barrier();                 // the previous slab's readers are done
        unpack(lane);
        barrier();
        if (k0 + BK < kHi) {
            fetch(k0 + BK, qw0, sc0, ktiles, kgroups, nt0, lane); // in flight during the math
        }
        [[unroll]] for (uint kt = 0u; kt < BK_TILES; kt++) {
            FRAG_A_T fragA[WM];
            FRAG_B_T fragB[WN];
            [[unroll]] for (uint i = 0u; i < WM; i++) {
                coopMatLoad(fragA[i], hact, pc.xnOff + (wm0 + i * TILE) * pc.lda + k0 + kt * TILE,
                    pc.lda, gl_CooperativeMatrixLayoutRowMajor);
            }
            [[unroll]] for (uint j = 0u; j < WN; j++) {
                coopMatLoad(fragB[j], sQB, (j * TILE) * LDS_ROW + kt * TILE, LDS_ROW,
                    gl_CooperativeMatrixLayoutColumnMajor);
            }
            [[unroll]] for (uint i = 0u; i < WM; i++) {
                [[unroll]] for (uint j = 0u; j < WN; j++) {
                    acc[i][j] = coopMatMulAdd(fragA[i], fragB[j], acc[i][j]);
                }
            }
        }
    }

    uint out0 = pc.outOff + slice * pc.gemmM * pc.gemmN;
    [[unroll]] for (uint i = 0u; i < WM; i++) {
        [[unroll]] for (uint j = 0u; j < WN; j++) {
            coopMatStore(acc[i][j], act, out0 + (wm0 + i * TILE) * pc.gemmN + wn0 + j * TILE, pc.gemmN,
                gl_CooperativeMatrixLayoutRowMajor);
        }
    }
}
'''
