	fmt.Printf("loaded   %s bank in %v\n", g.Bank, time.Since(start).Round(time.Millisecond))

	f, err := os.Open(*suite)
	must(err)
	defer f.Close()
	var w *bufio.Writer
	if *out != "" {
		of, err := os.Create(*out)
		must(err)
		defer of.Close()
		w = bufio.NewWriter(of)
		defer w.Flush()
	}

	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 64<<20)
	var rows []row
	var gpu time.Duration
	records := 0
	start = time.Now()
	for sc.Scan() {
		if *limit > 0 && records >= *limit {
			break
		}
		line := sc.Bytes()
		req, err := kev.ParseRequest(line)
		must(err)
		var lab struct {
			Questions map[string]struct {
				Label json.RawMessage `json:"label"`
				Src   string          `json:"src"`
			} `json:"questions"`
			Meta struct {
				ID      string `json:"id"`
				Source  string `json:"source"`
				Variant string `json:"variant"`
			} `json:"_meta"`
		}
		must(json.Unmarshal(line, &lab))
		rec, meta := kev.ToRecord(req)
		e, err := enc.Encode(rec, kev.MaxState, kev.MaxRow)
		must(err)
		probs, pass, err := g.Probs(e)
		must(err)
		gpu += pass.GPU
		for k, m := range meta {
			q := lab.Questions[m.ID]
			r := row{ID: lab.Meta.ID, Question: m.ID, Variant: lab.Meta.Variant, Source: lab.Meta.Source,
				Task: q.Src, Type: m.Type, Keys: m.Keys, Label: labelIndex(m, q.Label), P: probs[k]}
			rows = append(rows, r)
			if w != nil {
				b, _ := json.Marshal(r)
				w.Write(append(b, '\n'))
			}
		}
		records++
	}
	must(sc.Err())
	wall := time.Since(start)
	fmt.Printf("records  %d (%d questions) in %v, %v of GPU (%.1f ms a record)\n", records, len(rows),
		wall.Round(time.Millisecond), gpu.Round(time.Millisecond), float64(gpu.Microseconds())/1000/float64(records))
	report(rows)
}

// labelIndex is kev.benchmark.labels: a choice's label is its key, a noul's
// is a bool (int(True) is 1, the "true" slot), a score's is the level index.
func labelIndex(m kev.Meta, raw json.RawMessage) int {
	switch m.Type {
	case kev.TypeChoice:
		var k string
		must(json.Unmarshal(raw, &k))
		for i, key := range m.Keys {
			if key == k {
				return i
			}
		}
		log.Fatalf("label %q is not an option of %v", k, m.Keys)
	case kev.TypeNoul:
		var b bool
		if json.Unmarshal(raw, &b) == nil {
			if b {
				return 1
			}
			return 0
		}
	}
	var n float64
	must(json.Unmarshal(raw, &n))
	return int(n)
}

func argmax(p []float64) int {
	best := 0
	for i, v := range p {
		if v > p[best] {
			best = i
		}
	}
	return best
}

// report is accuracy over clean, knowable rows, overall and by task.
func report(rows []row) {
	type acc struct{ n, right int }
	all := acc{}
	byTask := map[string]*acc{}
	for _, r := range rows {
		if r.Variant != "clean" || r.Source == "unknowable" {
			continue
		}
		a := byTask[r.Task]
		if a == nil {
			a = &acc{}
			byTask[r.Task] = a
		}
		ok := argmax(r.P) == r.Label
		for _, x := range []*acc{a, &all} {
			x.n++
			if ok {
				x.right++
			}
		}
	}
	fmt.Printf("accuracy %.4f over %d clean questions\n", float64(all.right)/float64(max(all.n, 1)), all.n)
	tasks := make([]string, 0, len(byTask))
	for t := range byTask {
		tasks = append(tasks, t)
	}
	sort.Strings(tasks)
	for _, t := range tasks {
		a := byTask[t]
		fmt.Printf("  %-28s %4d  %.3f\n", t, a.n, float64(a.right)/float64(a.n))
	}
}

func readRows(path string) map[string]row {
	f, err := os.Open(path)
	must(err)
	defer f.Close()
	out := map[string]row{}
	sc := bufio.NewScanner(f)
	sc.Buffer(make([]byte, 1<<20), 64<<20)
	for sc.Scan() {
		var r row
		must(json.Unmarshal(sc.Bytes(), &r))
		out[r.ID+"/"+r.Question] = r
	}
	must(sc.Err())
	return out
}

// compareRows reports how far b's distributions are from a's: argmax
// agreement, the largest and mean max-|dp| per question, and each side's
// clean accuracy.
func compareRows(a, b map[string]row) {
	var n, agree int
	var worst, sum float64
	var worstID string
	for id, ra := range a {
		rb, ok := b[id]
		if !ok {
			continue
		}
		n++
		if argmax(ra.P) == argmax(rb.P) {
			agree++
		}
		d := 0.0
		for i := range ra.P {
			d = math.Max(d, math.Abs(ra.P[i]-rb.P[i]))
		}
		sum += d
		if d > worst {
			worst, worstID = d, id
		}
	}
	fmt.Printf("questions %d in both; argmax agreement %d/%d (%.4f); max |dp| %.4f (%s); mean max |dp| %.5f\n",
		n, agree, n, float64(agree)/float64(max(n, 1)), worst, worstID, sum/float64(max(n, 1)))
	for _, side := range []struct {
		name string
		rows map[string]row
	}{{"a", a}, {"b", b}} {
		var rs []row
		for _, r := range side.rows {
			rs = append(rs, r)
		}
		fmt.Printf("%s: ", side.name)
		report(rs)
	}
}

func openDevice() (*vk.Device, func()) {
	inst, err := vk.NewInstance("kev")
	must(err)
	devices, err := inst.PhysicalDevices()
	must(err)
	if len(devices) == 0 {
		log.Fatal("no Vulkan devices")
	}
	phys := &devices[0]
	for i := range devices {
		if devices[i].DeviceID == strixHaloDeviceID {
			phys = &devices[i]
		}
	}
	qf, err := phys.ComputeQueueFamily()
	must(err)
	sgs, err := phys.SubgroupSizeControl()
	must(err)
	dev, err := vk.NewDevice(phys, qf, vk.DeviceFeatures{Float16: true, CoopMatrix: true, SubgroupSizeControl: sgs.Supported})
	must(err)
	fmt.Printf("device   %s\n", phys.Name)
	return dev, func() { dev.Destroy(); inst.Destroy() }
}

func must(err error) {
	if err != nil {
		log.Fatal(err)
	}
}

