150		bm, bn int
151		waves  int
152	}
153	
154	// The rungs zimage/qwen's PlanFor chooses between for a 2560-wide Qwen, which
155	// this is.
156	var gemmKernels = []gemmKernel{
157		{"reg32x128", shaders.DiTGEMMReg32x128Tiled, 32, 128, 1},
158		{"reg64", shaders.DiTGEMMReg64Tiled, 64, 64, 1},
159		{"wg128x256", shaders.DiTGEMMWG128x256TiledSWZ8, 128, 256, 4},
160	}
161	
162	// gemmFor is zimage/qwen's measured schedule for hidden 2560.
163	func gemmFor(rows int) gemmKernel {
164		switch {
165		case rows <= 96:
166			return gemmKernels[0]
167		case rows <= 192:
168			return gemmKernels[1]
169		default:
170			return gemmKernels[2]
171		}
172	}
173	
174	// proj is one projection's place in a bank.
175	type proj struct {
176		off  uint32 // halves on the fp16 bank, bytes on the int8 one
177		n, k int
178	}
179	
180	type layerWeights struct {
181		attn bool
182		bank int
183		// fp16 bank
184		in, out, gate, up, down proj
185		// fp32 arena
186		inNorm, postNorm uint32
187		conv, gates      uint32 // GDN: taps [8192][4]; -exp(A_log) [32] then dt_bias [32]
188		gnorm            uint32 // GDN: the gated norm's plain weight [128]
189		qkNorm           uint32 // attention: q_norm (1+w) [256] then k_norm (1+w) [256]
190		// act arena, per layer
191		state, tail uint32 // GDN: S [32][128][128]; conv tail [3][8192]
192		kc, vc      uint32 // attention: key and value caches [cells][4][256]
193	}
194	
195	// GPU is a loaded Kev-4B.
196	type GPU struct {
197		Bank Bank
198		Cfg  *Config
199		Head *Head
200		Norm []float32 // the final norm, (1 + w)
201	
202		dev   *vk.Device
203		wbuf  *vk.Buffer
204		abuf  *vk.Buffer
205		hbuf  *vk.Buffer
206		banks []*vk.Buffer
207		pipes map[string]*vk.ComputePipeline
208		gemms []map[string]*vk.ComputePipeline
209		mods  []*vk.ShaderModule
210	
211		embed []uint16 // bf16 [vocab][hidden], gathered on the host
212	
213		// GEMM names a rung to use at every length instead of the schedule, for
214		// the ladder; empty is the schedule.
215		GEMM string
216		// LayersPerSubmit is how many layers go into one command buffer (see
217		// ForwardRows). Load sets 8.
218		LayersPerSubmit int
219	
220		rows  int // arena rows: the longest pass
221		cells int // attention cache cells
222		w     []layerWeights
223		rope  uint32
224	
225		// act arena
226		aX, aP, aG, aO, aY, aMeta, aSeg uint32
227		actElems                        int
228		// fp16 arena
229		hA     uint32
230		hElems int
231		lda    int // the widest A operand's row stride
232	}
233	
234	// Load builds the model from Kev's checkpoint directory (adapter, head,
235	// tokenizer) and the base it names, for passes of at most maxTokens packed
236	// tokens.
237	func Load(dev *vk.Device, kevDir, baseDir string, maxTokens int) (*GPU, error) {
238		return LoadBank(dev, kevDir, baseDir, maxTokens, BankQ8)
239	}
240	
241	// LoadBank is Load with the weight width named.
242	func LoadBank(dev *vk.Device, kevDir, baseDir string, maxTokens int, bank Bank) (*GPU, error) {
243		cfg, err := LoadConfig(baseDir)
244		if err != nil {
245			return nil, err
246		}
247		head, err := LoadHead(kevDir)
248		if err != nil {
249			return nil, err
250		}
251		if head.Dim <= 0 || len(head.QW) != head.Dim*cfg.Hidden {
252			return nil, fmt.Errorf("kev: head is %d x %d, want %d x %d", len(head.QW)/max(head.Dim, 1), head.Dim, head.Dim, cfg.Hidden)
253		}
254		ad, err := OpenAdapter(kevDir)
255		if err != nil {
256			return nil, err
257		}
258		defer ad.Close()
259		set, err := safetensors.OpenSet(baseDir)
260		if err != nil {
261			return nil, err
262		}
263		defer set.Close()
264	
265		g := &GPU{Bank: bank, Cfg: cfg, Head: head, dev: dev, pipes: map[string]*vk.ComputePipeline{}, LayersPerSubmit: 8}
266		g.rows = roundUp(maxTokens, rowAlign)
267		g.cells = g.rows
268		g.lda = cfg.Intermediate + gemmPad
269		if err := g.layout(); err != nil {
270			g.Destroy()
271			return nil, err
272		}
273		if err := g.build(); err != nil {
274			g.Destroy()
275			return nil, err
276		}
277		if err := g.stage(set, ad); err != nil {
278			g.Destroy()
279			return nil, err
280		}
281		return g, nil
282	}
283	
284	func roundUp(n, m int) int { return (n + m - 1) / m * m }
285	
286	func groups(n, per int) uint32 { return uint32((n + per - 1) / per) }
287	
288	// Rows is the longest pass this instance runs.
289	func (g *GPU) Rows() int { return g.rows }
290	
291	// layout plans every arena and allocates them.
292	func (g *GPU) layout() error {
293		c := g.Cfg
294		R := g.rows
295		// fp32 weights: rope table, final norm, then per layer.
296		w32 := 0
297		alloc32 := func(n int) uint32 { off := uint32(w32); w32 += (n + 63) &^ 63; return off }
298		g.rope = alloc32(2 * ropeRows * 32)
299	
300		// act arena.
301		alloc := func(n int) uint32 { off := uint32(g.actElems); g.actElems += (n + 63) &^ 63; return off }
302		g.aX = alloc(R * c.Hidden)
303		g.aP = alloc(R * 2 * c.Intermediate) // >= gdnN and attnN, and holds gate and up side by side
304		g.aG = alloc(R * (2048 + 2048 + 4096 + 32 + 32))
305		g.aO = alloc(R * 4096)
306		g.aY = alloc(R * c.Hidden)
307		g.aMeta = alloc(R * 4)
308		g.aSeg = alloc((R/4 + 2) * 2)
309	
310		// Banks are counted in bytes. A matrix is n*k halves on the fp16 bank,
311		// and n*k bytes plus an fp16 scale per 32 on the int8 one, rounded up to
312		// sixteen so the next matrix's words are aligned.
313		size := func(n, k int) int {
314			if g.Bank == BankQ8 {
315				return (n*k + n*k/q8Group*2 + 15) &^ 15
316			}
317			return n * k * 2
318		}
319		bankBytes := []int{0}
320		put := func(n, k int) proj {
321			at := bankBytes[len(bankBytes)-1]
322			off := at
323			if g.Bank == BankFP16 {
324				off /= 2
325			}
326			bankBytes[len(bankBytes)-1] += size(n, k)
327			return proj{off: uint32(off), n: n, k: k}
328		}
329		g.w = make([]layerWeights, c.Layers)
330		for i := range g.w {
331			lw := layerWeights{attn: c.Attention(i)}
332			// A layer's projections all go in one bank: start a new one if the
333			// whole layer would not fit.
334			inN := gdnN
335			if lw.attn {
336				inN = attnN
337			}
338			layerBytes := size(inN, c.Hidden) + size(c.Hidden, 4096) + 3*size(c.Intermediate, c.Hidden)
339			if bankBytes[len(bankBytes)-1]+layerBytes > maxBankBytes {
340				bankBytes = append(bankBytes, 0)
341			}
342			lw.bank = len(bankBytes) - 1
343			lw.in = put(inN, c.Hidden)
344			lw.out = put(c.Hidden, 4096)
345			lw.gate = put(c.Intermediate, c.Hidden)
346			lw.up = put(c.Intermediate, c.Hidden)
347			lw.down = put(c.Hidden, c.Intermediate)
348	
349			lw.inNorm = alloc32(c.Hidden)
350			lw.postNorm = alloc32(c.Hidden)
351			if lw.attn {
352				lw.qkNorm = alloc32(2 * c.HeadDim)
353				lw.kc = alloc(g.cells * 4 * 256)
354				lw.vc = alloc(g.cells * 4 * 256)
355			} else {
356				lw.conv = alloc32(8192 * 4)
357				lw.gates = alloc32(64)
358				lw.gnorm = alloc32(128)
359				lw.state = alloc(32 * 128 * 128)
360				lw.tail = alloc(3 * 8192)
361			}
362			g.w[i] = lw
363		}
364		g.hA = 0
