760	// ropeTable is HF's cos and sin for the 64 rotary dims, [pos][32] each: fp32
761	// inv_freq = 1 / theta^(2i/64), times the fp32 position, then cos and sin of
762	// that fp32 product.
763	func ropeTable(c *Config) []float32 {
764		dims := int(float64(c.HeadDim) * c.RotaryFactor)
765		half := dims / 2
766		inv := make([]float32, half)
767		for i := range inv {
768			inv[i] = float32(1 / math.Pow(c.RopeTheta, float64(2*i)/float64(dims)))
769		}
770		out := make([]float32, 2*ropeRows*half)
771		for p := 0; p < ropeRows; p++ {
772			for i := 0; i < half; i++ {
773				f := float64(inv[i] * float32(p))
774				out[p*half+i] = float32(math.Cos(f))
775				out[ropeRows*half+p*half+i] = float32(math.Sin(f))
776			}
777		}
778		return out
779	}
