790	// upload writes the pass's embeddings, token metadata and segment table.
791	// Segment 0 is the state, [0, StateLen); segment k is question k's branch.
792	func (g *GPU) upload(enc *Encoding) (segs [][2]int, err error) {
793		c := g.Cfg
794		n := len(enc.IDs)
795		if n == 0 || n > g.rows {
796			return nil, fmt.Errorf("kev: a pass of %d tokens; this instance holds %d", n, g.rows)
797		}
798		x := make([]float32, n*c.Hidden)
799		for i, id := range enc.IDs {
800			if id < 0 || int(id)*c.Hidden >= len(g.embed) {
801				return nil, fmt.Errorf("kev: token id %d is outside the embedding table", id)
802			}
803			row := g.embed[int(id)*c.Hidden : (int(id)+1)*c.Hidden]
804			for j, b := range row {
805				x[i*c.Hidden+j] = math.Float32frombits(uint32(b) << 16)
806			}
807		}
808		g.abuf.WriteFloat32At(int(g.aX), x)
809	
810		segs = [][2]int{{0, enc.StateLen}}
811		for k := range enc.Decide {
812			lo, hi := enc.Branch(k)
813			segs = append(segs, [2]int{lo, hi - lo})
814		}
815		meta := make([]uint32, 4*n)
816		for s, sg := range segs {
817			for r := sg[0]; r < sg[0]+sg[1]; r++ {
818				meta[4*r] = uint32(enc.Pos[r])
819				meta[4*r+1] = uint32(s)
820				meta[4*r+2] = uint32(sg[0])
821			}
822		}
823		g.abuf.WriteUint32At(int(g.aMeta), meta)
824		tab := make([]uint32, 0, 2*len(segs))
825		for _, sg := range segs {
826			tab = append(tab, uint32(sg[0]), uint32(sg[1]))
827		}
828		g.abuf.WriteUint32At(int(g.aSeg), tab)
829		return segs, nil
830	}
