937	// Forward runs every layer over a packed encoding and returns the final-normed
938	// hidden state at its readout rows (every <decide> and </opt>).
939	func (g *GPU) Forward(enc *Encoding) (*Pass, error) {
940		var rows []int
941		for k := range enc.Decide {
942			rows = append(rows, enc.Decide[k])
943			rows = append(rows, enc.Opts[k]...)
944		}
945		return g.ForwardRows(enc, rows, len(g.w))
946	}
