948	// ForwardRows runs the first `layers` layers and returns the given rows of
949	// the residual stream -- final-normed only when every layer ran. It is the
950	// stagewise seam the K4 gate uses.
951	func (g *GPU) ForwardRows(enc *Encoding, rows []int, layers int) (*Pass, error) {
952		segs, err := g.upload(enc)
953		if err != nil {
954			return nil, err
955		}
956		n := len(enc.IDs)
957		var total time.Duration
958		// Layers are submitted LayersPerSubmit at a time: a submit is a fence
959		// wait, and 32 of them were ~8 ms of a 54 ms request. The cap is there
960		// because a long state's pass is seconds, and one command buffer that long
