// ropeTable is HF's cos and sin for the 64 rotary dims, [pos][32] each: fp32
// inv_freq = 1 / theta^(2i/64), times the fp32 position, then cos and sin of
// that fp32 product.
func ropeTable(c *Config) []float32 {
	dims := int(float64(c.HeadDim) * c.RotaryFactor)
	half := dims / 2
	inv := make([]float32, half)
	for i := range inv {
		inv[i] = float32(1 / math.Pow(c.RopeTheta, float64(2*i)/float64(dims)))
	}
	out := make([]float32, 2*ropeRows*half)
	for p := 0; p < ropeRows; p++ {
		for i := 0; i < half; i++ {
			f := float64(inv[i] * float32(p))
			out[p*half+i] = float32(math.Cos(f))
			out[ropeRows*half+p*half+i] = float32(math.Sin(f))
		}
	}
	return out
}

// ---- a pass

// Pass is what one forward reads back: the final-normed hidden state at every
// readout row, in the encoding's index space.
type Pass struct {
	Hidden map[int][]float32
	GPU    time.Duration // summed dispatch time
}

// upload writes the pass's embeddings, token metadata and segment table.
// Segment 0 is the state, [0, StateLen); segment k is question k's branch.
func (g *GPU) upload(enc *Encoding) (segs [][2]int, err error) {
	c := g.Cfg
	n := len(enc.IDs)
	if n == 0 || n > g.rows {
		return nil, fmt.Errorf("kev: a pass of %d tokens; this instance holds %d", n, g.rows)
	}
	x := make([]float32, n*c.Hidden)
	for i, id := range enc.IDs {
		if id < 0 || int(id)*c.Hidden >= len(g.embed) {
			return nil, fmt.Errorf("kev: token id %d is outside the embedding table", id)
		}
		row := g.embed[int(id)*c.Hidden : (int(id)+1)*c.Hidden]
		for j, b := range row {
			x[i*c.Hidden+j] = math.Float32frombits(uint32(b) << 16)
		}
	}
	g.abuf.WriteFloat32At(int(g.aX), x)

	segs = [][2]int{{0, enc.StateLen}}
	for k := range enc.Decide {
		lo, hi := enc.Branch(k)
		segs = append(segs, [2]int{lo, hi - lo})
	}
	meta := make([]uint32, 4*n)
	for s, sg := range segs {
		for r := sg[0]; r < sg[0]+sg[1]; r++ {
			meta[4*r] = uint32(enc.Pos[r])
			meta[4*r+1] = uint32(s)
			meta[4*r+2] = uint32(sg[0])
		}
	}
	g.abuf.WriteUint32At(int(g.aMeta), meta)
	tab := make([]uint32, 0, 2*len(segs))
	for _, sg := range segs {
		tab = append(tab, uint32(sg[0]), uint32(sg[1]))
	}
	g.abuf.WriteUint32At(int(g.aSeg), tab)
	return segs, nil
}

// layerGraph is one layer's dispatches over a pass of n rows in len(segs)
// segments, with labels.
func (g *GPU) layerGraph(i, n int, segs [][2]int) ([]vk.MultiDispatch, []string) {
	c := g.Cfg
	lw := &g.w[i]
	R := uint32(g.rows)
	eps := math.Float32bits(float32(c.RMSEps))
	k := gemmFor(n)
	if g.Bank == BankQ8 {
		k = q8For(n)
	}
	for _, r := range append(gemmKernels[:len(gemmKernels):len(gemmKernels)], q8Kernels...) {
		if r.name == g.GEMM {
			k = r
		}
	}
	tokPad := roundUp(n, k.bm)
	base := push{Tokens: uint32(n), Span: R, Eps: eps, Aux1: g.aMeta}

	var d []vk.MultiDispatch
	var labels []string
	add := func(pipe, label string, gx, gy uint32, pc push) {
		d = append(d, vk.MultiDispatch{Pipeline: g.pipes[pipe], GroupsX: gx, GroupsY: gy, PushConstants: pc.bytes()})
		labels = append(labels, label)
	}
	normF16 := func(label string, wOff uint32) {
		pc := base
		pc.InOff, pc.OutOff, pc.WOff = g.aX, g.hA, wOff
		pc.Dim, pc.LDA = uint32(c.Hidden), uint32(c.Hidden+gemmPad)
		add("normf16", label, uint32(n), 1, pc)
	}
	gemm := func(label string, p proj, cOff uint32, lda int) {
		if g.Bank == BankQ8 {
			pc := llmPush{xnOff: g.hA, outOff: cOff, bOff: p.off, lda: uint32(lda),
				gemmM: uint32(tokPad), gemmN: uint32(p.n), gemmK: uint32(p.k)}
			d = append(d, vk.MultiDispatch{Pipeline: g.gemms[lw.bank][k.name], GroupsX: uint32(p.n / k.bn),
				GroupsY: uint32(tokPad / k.bm), PushConstants: pc.bytes()})
			labels = append(labels, label)
			return
		}
		pc := base
		pc.InOff, pc.OutOff, pc.BOff = g.hA, cOff, p.off
		pc.GemmM, pc.GemmN, pc.GemmK = uint32(tokPad), uint32(p.n), uint32(p.k)
		pc.LDA = uint32(lda)
		d = append(d, vk.MultiDispatch{Pipeline: g.gemms[lw.bank][k.name], GroupsX: uint32(p.n / k.bn), GroupsY: uint32(tokPad / k.bm), PushConstants: pc.bytes()})
		labels = append(labels, label)
	}
	residual := func(label string) {
		pc := base
		pc.InOff, pc.OutOff, pc.Dim = g.aY, g.aX, uint32(c.Hidden)
		add("add", label, uint32(n), 1, pc)
	}

	normF16("in norm", lw.inNorm)
	gemm("in proj", lw.in, g.aP, c.Hidden+gemmPad)
	if lw.attn {
		pc := base
		pc.InOff, pc.OutOff, pc.WOff = g.aP, g.aG, lw.qkNorm
		pc.KOff, pc.VOff, pc.KStride = lw.kc, lw.vc, 0
		pc.Aux0, pc.Aux2 = uint32(lw.in.n), g.rope
		pc.Span = ropeRows
		add("attnprep", "attn prep", uint32(n), 1, pc)

		pc = base
		pc.InOff, pc.OutOff = g.aG, g.hA
		pc.KOff, pc.VOff, pc.KStride = lw.kc, lw.vc, 0
		pc.GemmK, pc.Aux0 = g.aP, uint32(lw.in.n)
		pc.Aux2 = uint32(segs[0][1])
		pc.LDA = uint32(4096 + gemmPad)
		add("attention", "attention", uint32(n), 4, pc)
	} else {
		pc := base
		pc.InOff, pc.OutOff, pc.WOff, pc.KOff = g.aP, g.aG, lw.conv, lw.gates
		pc.Aux0, pc.Aux2, pc.VOff = uint32(lw.in.n), uint32(segs[0][1]), lw.tail
		add("gdnprep", "gdn prep", uint32(n), 1, pc)

		pc = base
		pc.InOff, pc.OutOff, pc.KOff, pc.Aux1 = g.aG, g.aO, lw.state, g.aSeg
		pc.Aux0, pc.Aux2 = 0, 2 // the state, from zero, keeping its final S
		add("gdnscan", "gdn scan state", 32, 1, pc)
		if len(segs) > 1 {
			pc.Aux0, pc.Aux2 = 1, 1 // every branch, from the state's S
			add("gdnscan", "gdn scan branches", 32, uint32(len(segs)-1), pc)
		}

		pc = base
		pc.InOff, pc.KOff, pc.WOff, pc.OutOff = g.aO, g.aP, lw.gnorm, g.hA
		pc.Aux0, pc.LDA = uint32(lw.in.n), uint32(4096+gemmPad)
		add("gdnnorm", "gdn norm", uint32(n), 1, pc)
	}
	gemm("out proj", lw.out, g.aY, 4096+gemmPad)
	residual("mixer residual")

	normF16("post norm", lw.postNorm)
	gemm("gate", lw.gate, g.aP, c.Hidden+gemmPad)
	gemm("up", lw.up, g.aP+R*uint32(c.Intermediate), c.Hidden+gemmPad)
	pc := base
	pc.InOff, pc.KOff, pc.OutOff = g.aP, g.aP+R*uint32(c.Intermediate), g.hA
	pc.Dim, pc.LDA, pc.Scale = uint32(c.Intermediate), uint32(g.lda), math.Float32bits(1)
	add("swiglu", "swiglu", uint32(n), 1, pc)
	gemm("down", lw.down, g.aY, g.lda)
	residual("mlp residual")
	return d, labels
}

// Forward runs every layer over a packed encoding and returns the final-normed
// hidden state at its readout rows (every <decide> and </opt>).
func (g *GPU) Forward(enc *Encoding) (*Pass, error) {
	var rows []int
	for k := range enc.Decide {
		rows = append(rows, enc.Decide[k])
		rows = append(rows, enc.Opts[k]...)
	}
	return g.ForwardRows(enc, rows, len(g.w))
}

// ForwardRows runs the first `layers` layers and returns the given rows of
// the residual stream -- final-normed only when every layer ran. It is the
// stagewise seam the K4 gate uses.
func (g *GPU) ForwardRows(enc *Encoding, rows []int, layers int) (*Pass, error) {
	segs, err := g.upload(enc)
	if err != nil {
		return nil, err
	}
	n := len(enc.IDs)
	var total time.Duration
	// Layers are submitted LayersPerSubmit at a time: a submit is a fence
	// wait, and 32 of them were ~8 ms of a 54 ms request. The cap is there
	// because a long state's pass is seconds, and one command buffer that long
	// can outlive the driver's reset watchdog (zimage/qwen's perSubmit).
	per := max(g.LayersPerSubmit, 1)
	if n > 2048 {
		per = 1
	}
	for i := 0; i < layers; i += per {
		var d []vk.MultiDispatch
		var labels []string
		for j := i; j < min(i+per, layers); j++ {
			dj, lj := g.layerGraph(j, n, segs)
			d, labels = append(d, dj...), append(labels, lj...)
		}
		dur, err := vk.DispatchMultiTimed(d, 1, 1, true)
		if err != nil {
			return nil, fmt.Errorf("kev: layers %d.. (%s): %w", i, strings.Join(labels, ","), err)
		}
		total += dur
	}
	p := &Pass{Hidden: map[int][]float32{}, GPU: total}
	for _, r := range rows {
		h := g.abuf.ReadFloat32At(int(g.aX)+r*g.Cfg.Hidden, g.Cfg.Hidden)
		if layers == len(g.w) {
			h = g.finalNorm(h)
		}
		p.Hidden[r] = h
	}
	return p, nil
}

// finalNorm is HF's Qwen3_5RMSNorm on one row, in fp32: x * rsqrt(mean(x^2)
// + eps) * (1 + w).
func (g *GPU) finalNorm(x []float32) []float32 {
	var ss float32
	for _, v := range x {
		ss += v * v
	}
	inv := float32(1 / math.Sqrt(float64(ss/float32(len(x))+float32(g.Cfg.RMSEps))))
	out := make([]float32, len(x))
	for i, v := range x {
		out[i] = v * inv * g.Norm[i]
	}
	return out
}

// Probs runs a pass and the pointer head: per question, the calibrated
// distribution over its options.
func (g *GPU) Probs(enc *Encoding) ([][]float64, *Pass, error) {
	p, err := g.Forward(enc)
	if err != nil {
		return nil, nil, err
	}
	out := make([][]float64, len(enc.Decide))
	for k, d := range enc.Decide {
		opts := make([][]float32, len(enc.Opts[k]))
		for j, o := range enc.Opts[k] {
			opts[j] = p.Hidden[o]
		}
		out[k] = Softmax(g.Head.Logits(p.Hidden[d], opts, g.Head.Temperature))
	}
	return out, p, nil
}

// Profile runs a pass one dispatch at a time and sums the GPU time by label
// over the layers. It is a measurement of the kernels, not of a pass: every
// dispatch pays its own submit.
func (g *GPU) Profile(enc *Encoding) (map[string]time.Duration, error) {
	segs, err := g.upload(enc)
	if err != nil {
		return nil, err
	}
	out := map[string]time.Duration{}
	for i := range g.w {
		d, labels := g.layerGraph(i, len(enc.IDs), segs)
		for j := range d {
			dur, err := vk.DispatchMultiTimed(d[j:j+1], 1, 1, true)
			if err != nil {
				return nil, fmt.Errorf("kev: layer %d %s: %w", i, labels[j], err)
			}
			out[labels[j]] += dur
		}
	}
	return out, nil
}

