// KV cells [0, stateLen), each GDN layer's S and conv tail -- which the last
// pass that held this state left behind, or which the prefix cache restored.
type pass struct {
	n         int
	withState bool
	stateLen  int      // the state's tokens, whether in this pass or not
	segs      [][2]int // pass rows: [0] the state ({0, 0} when it is not here), then branches
	src       []int    // encoding index of each pass row
	readouts  []int    // encoding indices to read back
}

// base is the attention cache cell of this pass's row 0.
func (p *pass) base() int {
	if p.withState {
		return 0
	}
	return p.stateLen
}

// plan cuts an encoding into passes of at most g.passRows() rows: one mixed
// pass when it fits and the state is not already resident; otherwise the
// state alone (unless resident) and then its branches, as many a pass as fit.
// A branch longer than a pass is an error, as it would be a 422 at the door.
func (g *GPU) plan(enc *Encoding, resident bool) ([]*pass, error) {
	limit := g.passRows()
	nq := len(enc.Decide)
	branch := func(k int) (int, int) { return enc.Branch(k) }
	readouts := func(k int) []int { return append([]int{enc.Decide[k]}, enc.Opts[k]...) }
	var out []*pass
	start := 0
	if !resident {
		if enc.StateLen > limit {
			return nil, fmt.Errorf("kev: a %d-token state does not fit a pass of %d", enc.StateLen, limit)
		}
		p := &pass{withState: true, stateLen: enc.StateLen, segs: [][2]int{{0, enc.StateLen}}}
		for r := 0; r < enc.StateLen; r++ {
			p.src = append(p.src, r)
		}
		// Branches ride along with the state while they fit.
		for ; start < nq; start++ {
			lo, hi := branch(start)
			if len(p.src)+hi-lo > limit {
				break
			}
			p.segs = append(p.segs, [2]int{len(p.src), hi - lo})
			for r := lo; r < hi; r++ {
				p.src = append(p.src, r)
			}
			p.readouts = append(p.readouts, readouts(start)...)
		}
		p.n = len(p.src)
		out = append(out, p)
	}
	for start < nq {
		p := &pass{stateLen: enc.StateLen, segs: [][2]int{{0, 0}}}
		for ; start < nq; start++ {
			lo, hi := branch(start)
			if hi-lo > limit {
				return nil, fmt.Errorf("kev: question %d is %d tokens, longer than a pass of %d", start, hi-lo, limit)
			}
			if len(p.src)+hi-lo > limit {
				break
			}
			p.segs = append(p.segs, [2]int{len(p.src), hi - lo})
			for r := lo; r < hi; r++ {
				p.src = append(p.src, r)
			}
			p.readouts = append(p.readouts, readouts(start)...)
		}
		p.n = len(p.src)
		out = append(out, p)
	}
	return out, nil
}

// passRows is the most rows a pass takes: the arena, or PassRows when a test
// asks for less.
func (g *GPU) passRows() int {
	if g.PassRows > 0 {
		return min(g.PassRows, g.rows)
	}
	return g.rows
}

// Pass is what one forward reads back: the final-normed hidden state at every
// readout row, in the encoding's index space.
type Pass struct {
	Hidden   map[int][]float32
	GPU      time.Duration // summed dispatch time, copies included
	Passes   int           // device passes the request took
	CacheHit bool          // the state came from the prefix cache
}

// upload writes a pass's embeddings, token metadata and segment table.
func (g *GPU) upload(enc *Encoding, p *pass) error {
	c := g.Cfg
	if p.n == 0 || p.n > g.rows {
		return fmt.Errorf("kev: a pass of %d tokens; this instance holds %d", p.n, g.rows)
	}
	if !p.withState && p.stateLen+p.n > g.cells {
		return fmt.Errorf("kev: a %d-token state and a %d-row pass overflow %d cache cells", p.stateLen, p.n, g.cells)
	}
	x := make([]float32, p.n*c.Hidden)
	for i, e := range p.src {
		id := enc.IDs[e]
		if id < 0 || int(id)*c.Hidden >= len(g.embed) {
			return fmt.Errorf("kev: token id %d is outside the embedding table", id)
		}
		row := g.embed[int(id)*c.Hidden : (int(id)+1)*c.Hidden]
		for j, b := range row {
			x[i*c.Hidden+j] = math.Float32frombits(uint32(b) << 16)
		}
	}
	g.abuf.WriteFloat32At(int(g.aX), x)

	meta := make([]uint32, 4*p.n)
	for s, sg := range p.segs {
		for r := sg[0]; r < sg[0]+sg[1]; r++ {
			meta[4*r] = uint32(enc.Pos[p.src[r]])
			meta[4*r+1] = uint32(s)
			meta[4*r+2] = uint32(sg[0])
		}
	}
	g.abuf.WriteUint32At(int(g.aMeta), meta)
	tab := make([]uint32, 0, 2*len(p.segs))
	for _, sg := range p.segs {
		tab = append(tab, uint32(sg[0]), uint32(sg[1]))
	}
