			if !g.w[i].attn {
				g.abuf.ZeroFloat32At(int(g.w[i].tail), 3*8192)
			}
		}
	}
	return nil
}

// layerGraph is one layer's dispatches over a pass, with labels.
func (g *GPU) layerGraph(i int, p *pass) ([]vk.MultiDispatch, []string) {
	c := g.Cfg
	lw := &g.w[i]
