// Pass is what one forward reads back: the final-normed hidden state at every
// readout row, in the encoding's index space.
type Pass struct {
	Hidden   map[int][]float32
	GPU      time.Duration // summed dispatch time, copies included
	Passes   int           // device passes the request took
	CacheHit bool          // the state came from the prefix cache
}

// upload writes a pass's embeddings, token metadata and segment table.
func (g *GPU) upload(enc *Encoding, p *pass) error {
	c := g.Cfg
	if p.n == 0 || p.n > g.rows {
		return fmt.Errorf("kev: a pass of %d tokens; this instance holds %d", p.n, g.rows)
	}
	if !p.withState && p.stateLen+p.n > g.cells {
		return fmt.Errorf("kev: a %d-token state and a %d-row pass overflow %d cache cells", p.stateLen, p.n, g.cells)
	}
	x := make([]float32, p.n*c.Hidden)
	for i, e := range p.src {
		id := enc.IDs[e]
		if id < 0 || int(id)*c.Hidden >= len(g.embed) {
			return fmt.Errorf("kev: token id %d is outside the embedding table", id)
		}
		row := g.embed[int(id)*c.Hidden : (int(id)+1)*c.Hidden]
		for j, b := range row {
			x[i*c.Hidden+j] = math.Float32frombits(uint32(b) << 16)
		}
	}
	g.abuf.WriteFloat32At(int(g.aX), x)

	meta := make([]uint32, 4*p.n)
	for s, sg := range p.segs {
		for r := sg[0]; r < sg[0]+sg[1]; r++ {
			meta[4*r] = uint32(enc.Pos[p.src[r]])
			meta[4*r+1] = uint32(s)
			meta[4*r+2] = uint32(sg[0])
		}
	}
	g.abuf.WriteUint32At(int(g.aMeta), meta)
	tab := make([]uint32, 0, 2*len(p.segs))
	for _, sg := range p.segs {
		tab = append(tab, uint32(sg[0]), uint32(sg[1]))
	}
	g.abuf.WriteUint32At(int(g.aSeg), tab)
	// A state shorter than the conv window leaves tail rows the prep kernel
	// never writes; they are the zeros before a sequence's start.
	if p.withState && p.stateLen < 3 {
		for i := range g.w {
			if !g.w[i].attn {
				g.abuf.ZeroFloat32At(int(g.w[i].tail), 3*8192)
			}
		}
	}
	return nil
}

