	c.pipe, err = g.dev.NewPipeline(c.mod, vk.PipelineSpec{
		Buffers:          []*vk.Buffer{g.wbuf, g.abuf, g.hbuf, g.banks[0], c.buf},
		PushConstantSize: pushBytes,
	})
	if err != nil {
		return nil, err
	}
	c.slots = make([]cacheSlot, n)
	return c, nil
}

func (c *prefixCache) destroy() {
	if c == nil {
		return
	}
	if c.pipe != nil {
		c.pipe.Destroy()
	}
	if c.mod != nil {
		c.mod.Destroy()
	}
	if c.buf != nil {
		c.buf.Destroy()
	}
}

// kvRow is one cell of one attention layer's K (or V): 4 heads of 256.
const kvRow = 4 * 256

// fits is whether a state of ls tokens can be cached.
func (c *prefixCache) fits(ls int) bool { return c != nil && len(c.slots) > 0 && ls <= c.cells }

// lookup returns the slot holding exactly this state, or -1, and counts it.
func (c *prefixCache) lookup(key []int32) int {
	if c == nil || len(c.slots) == 0 {
		return -1
	}
	for i := range c.slots {
		if c.slots[i].key != nil && slices.Equal(c.slots[i].key, key) {
			c.tick++
			c.slots[i].used = c.tick
			c.Hits++
			return i
		}
	}
	c.Misses++
	return -1
}

// copies is the dispatch list moving the working state to or from slot i:
// the GDN block whole, then each attention layer's first ls cells of K and V.
func (c *prefixCache) copies(g *GPU, slot, ls int, restore bool) []vk.MultiDispatch {
	var d []vk.MultiDispatch
	at := slot * c.slotFloats
	move := func(arena uint32, cache, n int) {
		pc := push{Dim: uint32(n)}
		if restore {
			pc.InOff, pc.OutOff, pc.Aux0 = uint32(cache), arena, 1
		} else {
			pc.InOff, pc.OutOff, pc.Aux0 = arena, uint32(cache), 0
		}
		d = append(d, vk.MultiDispatch{Pipeline: c.pipe, GroupsX: min(groups(n, 256), 1024), GroupsY: 1, PushConstants: pc.bytes()})
	}
	move(g.gdnBlock, at, c.gdnFloats)
	at += c.gdnFloats
	for _, lw := range g.w {
		if !lw.attn {
			continue
		}
		move(lw.kc, at, ls*kvRow)
		move(lw.vc, at+c.cells*kvRow, ls*kvRow)
		at += 2 * c.cells * kvRow
	}
	return d
}

// save copies the working state into the least recently used slot.
func (c *prefixCache) save(g *GPU, key []int32) (time.Duration, error) {
	victim := 0
	for i := range c.slots {
		if c.slots[i].key == nil {
			victim = i
			break
		}
		if c.slots[i].used < c.slots[victim].used {
			victim = i
		}
	}
	dur, err := vk.DispatchMultiTimed(c.copies(g, victim, len(key), false), 1, 1, true)
	if err != nil {
		return 0, fmt.Errorf("kev: saving a state: %w", err)
	}
	c.tick++
	c.slots[victim] = cacheSlot{key: slices.Clone(key), used: c.tick}
	c.Saves++
	return dur, nil
}

// restore copies slot i back into the working state.
func (c *prefixCache) restore(g *GPU, slot, ls int) (time.Duration, error) {
	dur, err := vk.DispatchMultiTimed(c.copies(g, slot, ls, true), 1, 1, true)
	if err != nil {
		return 0, fmt.Errorf("kev: restoring a state: %w", err)
	}
	return dur, nil
}

// clear forgets every slot.
func (c *prefixCache) clear() {
	if c == nil {
		return
	}
	for i := range c.slots {
		c.slots[i] = cacheSlot{}
	}
}

// CacheStats reports the prefix cache's counters.
func (g *GPU) CacheStats() (hits, misses, saves, slots, tokens int) {
	c := g.cache
	if c == nil {
		return
	}
	return c.Hits, c.Misses, c.Saves, len(c.slots), c.cells
}

// ClearCache forgets every cached state.
func (g *GPU) ClearCache() { g.cache.clear() }

