package kev

import "testing"

// TestProbeChunkLayouts is a throwaway probe for the 1.7e-6 chunking residue.
func TestProbeChunkLayouts(t *testing.T) {
	g := loadGPU(t)
	e := loadEncoder(t)
	enc := encodeFixture(t, e, loadFixtures(t)[0].Request)
	defer func() { g.PassRows = 0 }()
	g.ClearCache()
	ref, _, _ := g.Probs(enc)
	for _, pr := range []int{79, 60, 50, 42, 30} {
		g.ClearCache()
		g.PassRows = pr
		ps, err := g.plan(enc, false)
		if err != nil {
			t.Logf("rows %d: %v", pr, err)
			continue
		}
		var shape []int
		for _, p := range ps {
			shape = append(shape, p.n)
		}
		got, _, err := g.Probs(enc)
		if err != nil {
			t.Fatal(err)
		}
		same, worst := sameProbs(ref, got)
		t.Logf("rows %d: passes %v identical %v max %.2e", pr, shape, same, worst)
	}
}
EOF
go test ./kev/ -run 'TestProbeChunkLayouts' -v -timeout 20m 2>&1 | grep "rows "

