}

// prow names one pass row: which request, which index of its encoding.
type prow struct{ q, e int }

// pass is one forward over the device. Its rows are segments laid end to end:
// requests' states and branches. A request whose state is not in the pass
// runs against its slot and cells, which an earlier pass or the prefix cache
// left there.
type pass struct {
	reqs     []*preq
	src      []prow
	cell     []int
	meta     []uint32   // 8 words a row, as kev_gdn_prep.comp documents
	states   [][3]int   // state segments: first row, length, slot
	branches [][3]int   // branch segments, the same
	readouts []prow
	cursor   int        // the next free attention cell
	n        int
}

// keyAlign is the attention's key block (kev_attn_wmma's BN). Every state's
// and every branch's keys start on a multiple of it, so a key block never
// mixes two segments, and a row's attention is the same bits wherever its
// segment sits in the cache (K7.3).
const keyAlign = 64

// addState appends request q's state rows at its (aligned) cells.
func (p *pass) addState(q int) {
	r := p.reqs[q]
	r.stateRow = len(p.src)
	ls := r.enc.StateLen
	p.states = append(p.states, [3]int{len(p.src), ls, r.slot})
	for e := 0; e < ls; e++ {
		p.push(q, e, r.sLo+e, 0, len(p.src)-e+e-e, 0, 0)
	}
	// fix the rows' metadata now that the state's extent is known
	for i := r.stateRow; i < len(p.src); i++ {
		m := p.meta[8*i:]
		m[1], m[2], m[4], m[5], m[7] = 0, uint32(r.stateRow), 0, 0, uint32(r.stateRow+ls)
	}
	p.cursor = max(p.cursor, r.sLo+ls)
}

// fitsBranch is whether encoding rows [lo, hi) fit as a branch.
func (p *pass) fitsBranch(lo, hi, rows, cells int) bool {
	return len(p.src)+hi-lo <= rows && roundUp(p.cursor, keyAlign)+hi-lo <= cells
}

// addBranch appends request q's encoding rows [lo, hi) as a branch at the
// next aligned cell.
func (p *pass) addBranch(q, k int) {
	r := p.reqs[q]
	lo, hi := r.enc.Branch(k)
	at := roundUp(p.cursor, keyAlign)
	first := len(p.src)
	p.branches = append(p.branches, [3]int{first, hi - lo, r.slot})
	end := 0
	if r.withState {
		end = r.stateRow + r.enc.StateLen
	}
	for e := lo; e < hi; e++ {
		p.push(q, e, at+e-lo, 1, first, r.sLo, end)
