	p.src = append(p.src, prow{q, e})
	p.cell = append(p.cell, cell)
	sHi := sLo
	if branch == 1 {
		sHi = sLo + r.enc.StateLen
	}
	p.meta = append(p.meta, uint32(r.enc.Pos[e]), branch, uint32(segStart), uint32(cell),
		uint32(sLo), uint32(sHi), uint32(r.slot), uint32(stateEnd))
