			out = append(out, p)
			p = fresh(false)
			if !p.fitsBranch(lo, hi, limit, g.cells) {
				return nil, &OverflowError{Msg: fmt.Sprintf("question %d is %d tokens, longer than a pass of %d tokens (-kev-tokens)", k, hi-lo, limit)}
			}
		}
		p.addBranch(0, k)
	}
	p.n = len(p.src)
	return append(out, p), nil
}

