		for k := range enc.Decide {
			lo, hi := enc.Branch(k)
			if !p.fitsBranch(lo, hi, g.passRows(), g.cells) {
				return nil, false
			}
			p.addBranch(i, k)
		}
	}
	p.n = len(p.src)
	return p, p.n <= g.passRows() && p.n > 0
